insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('8d916894-efc7-4c1d-996f-3c71f8b878da', 'c876132a-c63c-4a00-bc2b-f40f32d682d6', 'orta'::difficulty_level, 'Uygurların yerleşik hayata geçmesiyle ilgili aşağıdakilerden hangisi doğrudur?', 'Uygurların yerleşik hayata geçişinin sonuçlarını bilir.', 'Uygurlar yerleşik hayata geçtikten sonra tarım ve şehircilikle uğraşmaya başlamış, bu da savaşçılık geleneğinin zayıflamasına yol açmıştır (bu doğru seçenektir). Diğer seçenekler ya Uygurlarla ilgisiz ya da tam tersi yönde yanlış bilgiler içerir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('8d916894-efc7-4c1d-996f-3c71f8b878da', 'Bu geçiş, Uygurların askerî gücünü ARTIRMIŞTIR.', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('8d916894-efc7-4c1d-996f-3c71f8b878da', 'Bu geçiş, Uygurların savaşçılık geleneğinin zayıflamasına yol açmıştır.', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('8d916894-efc7-4c1d-996f-3c71f8b878da', 'Bu geçiş, Göktürklerden önce gerçekleşmiştir.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('8d916894-efc7-4c1d-996f-3c71f8b878da', 'Bu geçiş, Kavimler Göçü''nün doğrudan nedenidir.', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('8d916894-efc7-4c1d-996f-3c71f8b878da', 'Bu geçiş, Büyük Hun İmparatorluğu döneminde yaşanmıştır.', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('2ca83210-580c-4919-90ca-f11325561dfe', '145d44b3-a8e7-430f-8778-71fb8929a97d', 'zor'::difficulty_level, 'Osmanlı Devleti''nde Divan-ı Hümayun''un düzenli hâle getirilmesi ve kadıaskerlik/beylerbeyilik makamlarının oluşturulması hangi hükümdar döneminde gerçekleşmiştir?', 'Osmanlı merkezi teşkilatının kuruluş dönemindeki gelişimini bilir.', 'Çandarlı Kara Halil''in önerisiyle kadıaskerlik ve beylerbeyilik makamları I. Murad (Hüdavendigâr) döneminde oluşturulmuş, Divan-ı Hümayun bu dönemde daha düzenli bir yapıya kavuşmuştur.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2ca83210-580c-4919-90ca-f11325561dfe', 'Osman Bey', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2ca83210-580c-4919-90ca-f11325561dfe', 'Orhan Bey', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2ca83210-580c-4919-90ca-f11325561dfe', 'I. Murad', true, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2ca83210-580c-4919-90ca-f11325561dfe', 'Yıldırım Bayezıd', false, 4);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2ca83210-580c-4919-90ca-f11325561dfe', 'Çelebi Mehmed', false, 0);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('ad0968c0-8a08-4e1c-b516-d0e59d45e99b', '091291bb-a136-48e2-94b1-8d12631be6ad', 'orta'::difficulty_level, 'Sakarya Meydan Muharebesi''nin (1921) sonuçlarıyla ilgili aşağıdakilerden hangisi doğrudur?', 'Sakarya Meydan Muharebesi''nin önemini bilir.', 'Sakarya Meydan Muharebesi sonrasında TBMM, Mustafa Kemal''e Başkomutanlık ve Mareşallik unvanı vermiştir; bu, savaşın en somut siyasi sonucudur.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('ad0968c0-8a08-4e1c-b516-d0e59d45e99b', 'Bu zafer sonrasında Lozan Antlaşması imzalanmıştır.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('ad0968c0-8a08-4e1c-b516-d0e59d45e99b', 'Bu zafer sonrasında TBMM, Mustafa Kemal''e Başkomutanlık ve Mareşallik unvanı vermiştir.', true, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('ad0968c0-8a08-4e1c-b516-d0e59d45e99b', 'Bu zafer, TBMM''nin İtilaf Devletlerince ilk kez tanınmasını sağlamıştır.', false, 4);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('ad0968c0-8a08-4e1c-b516-d0e59d45e99b', 'Bu zafer ile Kurtuluş Savaşı tamamen sona ermiştir.', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('ad0968c0-8a08-4e1c-b516-d0e59d45e99b', 'Bu zafer, Doğu Cephesi''nde kazanılmıştır.', false, 1);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('e3b5a4ee-c6d6-4e31-aded-425ff4c10fca', '3c087fbc-2d70-4b75-880e-8e2f9e4475fb', 'kolay'::difficulty_level, 'Kabotaj Kanunu (1926) ile ilgili aşağıdakilerden hangisi doğrudur?', 'Ekonomik inkılapları bilir.', 'Kabotaj Kanunu ile Türk karasularında taşımacılık yalnızca Türk gemilerine bırakılmış, bu da millî ekonomiyi güçlendirmeyi amaçlayan ekonomik inkılaplardan biri olmuştur.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e3b5a4ee-c6d6-4e31-aded-425ff4c10fca', 'Türk karasularında taşımacılık yalnızca Türk gemilerine bırakılmıştır.', true, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e3b5a4ee-c6d6-4e31-aded-425ff4c10fca', 'Bu kanun, kadınlara seçme-seçilme hakkı tanımıştır.', false, 4);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e3b5a4ee-c6d6-4e31-aded-425ff4c10fca', 'Bu kanun, halifeliği kaldırmıştır.', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e3b5a4ee-c6d6-4e31-aded-425ff4c10fca', 'Bu kanun, Latin harflerine geçişi sağlamıştır.', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e3b5a4ee-c6d6-4e31-aded-425ff4c10fca', 'Bu kanun, Medeni Kanun''un bir parçasıdır.', false, 2);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('890a7dbd-76ef-4b02-8409-5cb1fb600484', '44672589-4a32-4299-951a-afa51d7c3099', 'orta'::difficulty_level, 'Yusuf Has Hacib tarafından yazılan ve Türk-İslam siyaset anlayışını yansıtan eser aşağıdakilerden hangisidir?', 'Karahanlı dönemi eserlerini bilir.', 'Kutadgu Bilig, Yusuf Has Hacib tarafından Karahanlı hükümdarına sunulmak üzere yazılmış, hükümdarlık erdemlerini ve devlet yönetimi anlayışını konu alan bir eserdir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('890a7dbd-76ef-4b02-8409-5cb1fb600484', 'Divan-ı Lügati''t Türk', false, 4);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('890a7dbd-76ef-4b02-8409-5cb1fb600484', 'Kutadgu Bilig', true, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('890a7dbd-76ef-4b02-8409-5cb1fb600484', 'Divan-ı Hikmet', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('890a7dbd-76ef-4b02-8409-5cb1fb600484', 'Şehname', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('890a7dbd-76ef-4b02-8409-5cb1fb600484', 'Atabetü''l Hakayık', false, 3);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('b3fc0de8-6c1a-44bc-b2f2-b0fb1c8d4a00', '73d24254-55ed-43ae-8627-1456e48059b4', 'orta'::difficulty_level, 'Türkiye''nin matematik konumunun bir sonucu olarak aşağıdakilerden hangisi gösterilebilir?', 'Matematik konum sonuçlarını özel konum sonuçlarından ayırt eder.', 'Yerel saat farkının doğu-batı yönünde değişmesi, doğrudan Türkiye''nin bulunduğu boylamlar (matematik konum) ile ilgilidir. Diğer seçenekler (komşu sayısı, jeopolitik önem, boğazlara sahip olma) özel konumun sonuçlarıdır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b3fc0de8-6c1a-44bc-b2f2-b0fb1c8d4a00', 'Doğu-batı yönünde yerel saatin farklı olması.', true, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b3fc0de8-6c1a-44bc-b2f2-b0fb1c8d4a00', 'Çok sayıda komşu ülkeye sahip olması.', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b3fc0de8-6c1a-44bc-b2f2-b0fb1c8d4a00', 'Önemli boğazlara (İstanbul-Çanakkale) sahip olması.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b3fc0de8-6c1a-44bc-b2f2-b0fb1c8d4a00', 'Jeopolitik açıdan önemli bir konumda bulunması.', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b3fc0de8-6c1a-44bc-b2f2-b0fb1c8d4a00', 'Enerji nakil hatlarının güzergâhında yer alması.', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('7131469c-a924-40a7-8448-bcd51680e08e', 'f4bdef2c-d148-4d88-832f-731b8e3d122c', 'zor'::difficulty_level, 'Karadeniz İklimi ile ilgili aşağıdaki bilgilerden hangisi doğrudur?', 'Karadeniz ikliminin özelliklerini bilir.', 'Karadeniz iklimi her mevsim yağışlı olması ve yıllık yağış miktarının fazla olmasıyla bilinir; en fazla yağış sonbahar-kış aylarında, en az yağış ise ilkbahar-yaz aylarında görülür ama hiçbir mevsimde kurak bir dönem yaşanmaz.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('7131469c-a924-40a7-8448-bcd51680e08e', 'Yazları kurak, kışları yağışlıdır (Akdeniz iklimiyle aynıdır).', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('7131469c-a924-40a7-8448-bcd51680e08e', 'Her mevsim yağışlıdır, kurak mevsimi yoktur.', true, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('7131469c-a924-40a7-8448-bcd51680e08e', 'Yıllık yağış miktarı Türkiye''nin en az yağış alan bölgesidir.', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('7131469c-a924-40a7-8448-bcd51680e08e', 'Yazları en fazla, kışları en az yağış alır.', false, 4);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('7131469c-a924-40a7-8448-bcd51680e08e', 'Karasal bir iklim türüdür, deniz etkisi görülmez.', false, 0);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('040d4dd5-8322-4cea-bef4-e7fe7cda15e8', '6b76a27b-b27e-4065-8325-d027f3f3377a', 'orta'::difficulty_level, 'Türkiye''de nüfusun kıyı bölgelerde iç kesimlere göre daha yoğun olmasının temel nedeni aşağıdakilerden hangisidir?', 'Nüfus dağılışını etkileyen faktörleri bilir.', 'Kıyı bölgelerde iklim koşullarının daha ılıman olması, tarım, sanayi ve ticaret imkânlarının fazlalığı nüfusun kıyılarda yoğunlaşmasının temel nedenidir; iç kesimlerdeki yükseklik ve arazi engebeliliği ise nüfusu seyrekleştiren faktörlerdir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('040d4dd5-8322-4cea-bef4-e7fe7cda15e8', 'İç kesimlerin deprem riskinin daha yüksek olması.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('040d4dd5-8322-4cea-bef4-e7fe7cda15e8', 'Kıyı bölgelerdeki iklim, tarım, sanayi ve ticaret imkânlarının daha elverişli olması.', true, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('040d4dd5-8322-4cea-bef4-e7fe7cda15e8', 'İç kesimlerde su kaynaklarının bulunmaması.', false, 4);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('040d4dd5-8322-4cea-bef4-e7fe7cda15e8', 'Kıyı bölgelerin madencilik açısından daha zengin olması.', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('040d4dd5-8322-4cea-bef4-e7fe7cda15e8', 'İç kesimlerin tamamen ormanlık olması.', false, 1);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('2a428184-0cb3-4401-aed2-ba3f0646d077', '714f0c66-ba93-4fc8-8b82-9b0800a7350f', 'orta'::difficulty_level, 'Türkiye''de fay hatlarının yoğun olarak bulunmasının temel nedeni aşağıdakilerden hangisidir?', 'Türkiye''nin deprem riskinin jeolojik nedenini bilir.', 'Türkiye, Avrasya, Afrika ve Arabistan levhalarının birbirine yakınsadığı bir bölgede yer aldığı için levha hareketleri sonucu oluşan fay hatları bakımından zengindir; bu da ülkeyi deprem riski yüksek bir konuma getirir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2a428184-0cb3-4401-aed2-ba3f0646d077', 'Türkiye''nin üç tarafının denizlerle çevrili olması.', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2a428184-0cb3-4401-aed2-ba3f0646d077', 'Türkiye''nin aktif levha sınırları üzerinde (levhaların yakınsadığı bir bölgede) yer alması.', true, 4);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2a428184-0cb3-4401-aed2-ba3f0646d077', 'Türkiye''nin matematik konumunun 36-42 kuzey paralelleri arasında olması.', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2a428184-0cb3-4401-aed2-ba3f0646d077', 'Türkiye''de yağış rejiminin düzensiz olması.', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2a428184-0cb3-4401-aed2-ba3f0646d077', 'Türkiye''nin orman varlığının fazla olması.', false, 2);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('e4276877-e37f-4f6f-8df5-ea59f2ac1308', '307f95b7-0c09-47b4-b088-895dba797c11', 'zor'::difficulty_level, 'Türkiye''de demiryolu taşımacılığının karayoluna göre daha az tercih edilmesinin temel nedenleri arasında aşağıdakilerden hangisi gösterilemez?', 'Ulaşım türlerinin tercih nedenlerini ayırt eder.', 'Türkiye''nin genç bir arazi yapısına (dağlık-engebeli) sahip olması demiryolu yapımını zorlaştıran ve maliyetini artıran gerçek bir etkendir; bu nedenle bu seçenek DEMİRYOLUNU AZALTAN bir neden olarak doğru sayılır, dolayısıyla ''gösterilemez'' olan seçenek bu DEĞİLDİR. Doğru yanıt, demiryolu yapım/işletme maliyetinin karayoluna göre DAHA UCUZ olduğu yönündeki YANLIŞ öncüldür — gerçekte demiryolu yapımı başlangıçta karayoluna göre DAHA PAHALIDIR, bu yüzden bu iddia gösterilemez bir nedendir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e4276877-e37f-4f6f-8df5-ea59f2ac1308', 'Türkiye''nin dağlık ve engebeli bir arazi yapısına sahip olması.', false, 4);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e4276877-e37f-4f6f-8df5-ea59f2ac1308', 'Karayolu ağının demiryoluna göre daha erken ve yaygın biçimde geliştirilmiş olması.', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e4276877-e37f-4f6f-8df5-ea59f2ac1308', 'Demiryolu yapım ve işletme maliyetinin karayoluna göre daha ucuz olması.', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e4276877-e37f-4f6f-8df5-ea59f2ac1308', 'Kapıdan kapıya taşımacılıkta karayolunun daha esnek olması.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e4276877-e37f-4f6f-8df5-ea59f2ac1308', 'Özel sektör yatırımlarının çoğunlukla karayoluna yönelmiş olması.', false, 3);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('4737fbd6-13be-4c59-a8a4-a8e37f79fece', 'f046e8ff-0d47-47fa-add9-45a27a151b63', 'kolay'::difficulty_level, 'Örf ve adet hukuku ile ilgili aşağıdaki bilgilerden hangisi doğrudur?', 'Hukukun yazısız kaynağını bilir.', 'Örf ve adet hukuku, toplumda uzun süredir uygulanan ve devlet tarafından tanındığında bağlayıcı hâle gelen YAZISIZ bir hukuk kaynağıdır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('4737fbd6-13be-4c59-a8a4-a8e37f79fece', 'Yazılı bir hukuk kaynağıdır.', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('4737fbd6-13be-4c59-a8a4-a8e37f79fece', 'Yazısız bir hukuk kaynağıdır ve devletçe tanındığında bağlayıcı olur.', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('4737fbd6-13be-4c59-a8a4-a8e37f79fece', 'Yalnızca özel hukuk alanında geçerlidir.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('4737fbd6-13be-4c59-a8a4-a8e37f79fece', 'Anayasa''dan daha üstün bir norm kabul edilir.', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('4737fbd6-13be-4c59-a8a4-a8e37f79fece', 'Sadece kamu hukukunda uygulanır.', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('65a8e9ab-7cc8-402e-9e03-de7c7ae8819f', '86ae4cc1-2323-4a43-8448-b1fa4daf514e', 'zor'::difficulty_level, 'Türkiye Cumhuriyeti Anayasası''nın ''değiştirilemeyecek ve değiştirilmesi teklif dahi edilemeyecek'' hükümleri arasında aşağıdakilerden hangisi YER ALMAZ?', 'Anayasa''nın değiştirilemez hükümlerini bilir.', 'Milletvekili dokunulmazlığı Anayasa''nın değiştirilebilir hükümleri arasındadır; devletin şeklinin Cumhuriyet olması, başkentin Ankara olması, Türkçenin resmî dil olması ve millî marşın İstiklal Marşı olması ise Anayasa''nın ilk üç maddesinde yer alan ve değiştirilmesi teklif dahi edilemeyecek hükümlerdir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('65a8e9ab-7cc8-402e-9e03-de7c7ae8819f', 'Devletin şeklinin Cumhuriyet olması.', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('65a8e9ab-7cc8-402e-9e03-de7c7ae8819f', 'Başkentin Ankara olması.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('65a8e9ab-7cc8-402e-9e03-de7c7ae8819f', 'Milletvekillerinin yasama dokunulmazlığına sahip olması.', true, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('65a8e9ab-7cc8-402e-9e03-de7c7ae8819f', 'Türkçenin resmî dil olması.', false, 4);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('65a8e9ab-7cc8-402e-9e03-de7c7ae8819f', 'Millî marşın İstiklal Marşı olması.', false, 0);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('bf2820a3-85bc-4854-a957-41a2df93b190', '37c6d817-c011-4012-9f18-b651bf8b022e', 'orta'::difficulty_level, 'TBMM''nin bir kanunu, Cumhurbaşkanı''nın veto etmesine (bir daha görüşülmek üzere geri göndermesine) rağmen AYNEN kabul etmesi durumunda ne olur?', 'Yasama-yürütme ilişkisinde veto sürecini bilir.', 'TBMM bir kanunu aynen kabul ederse, Cumhurbaşkanı bu kanunu ARTIK VETO EDEMEZ ve yayımlamak zorundadır (bütçe kanunları hariç); bu, yasamanın yürütme karşısındaki son sözü söyleme yetkisidir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('bf2820a3-85bc-4854-a957-41a2df93b190', 'Cumhurbaşkanı kanunu bir kez daha veto edebilir.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('bf2820a3-85bc-4854-a957-41a2df93b190', 'Kanun, Anayasa Mahkemesi''nin onayına sunulur.', false, 3);
