insert into question_choices (question_id, choice_text, is_correct, order_index) values ('bf2820a3-85bc-4854-a957-41a2df93b190', 'Kanun otomatik olarak yürürlükten kalkar.', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('bf2820a3-85bc-4854-a957-41a2df93b190', 'TBMM''nin kanunu yeniden oylaması gerekir.', false, 1);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('05483f47-7b31-48b3-ad86-64f53621350d', 'a761a66c-9aa8-45fe-a865-b4833c71d0b2', 'orta'::difficulty_level, 'Anayasa''nın 15. maddesine göre olağanüstü hâllerde bile dokunulamayacak temel haklar arasında aşağıdakilerden hangisi YER ALIR?', 'Anayasa madde 15 kapsamındaki çekirdek hakları bilir.', 'Kişinin yaşam hakkı, maddi ve manevi varlığının bütünlüğü, din/vicdan/düşünce özgürlüğü gibi haklar olağanüstü hâllerde bile dokunulamayacak çekirdek haklardandır; seyahat özgürlüğü ise olağanüstü hâllerde sınırlandırılabilecek haklar arasındadır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('05483f47-7b31-48b3-ad86-64f53621350d', 'Seyahat özgürlüğü', false, 3);
