insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('a8f0613d-dba9-4233-badd-b48be8530583', 'dafcd822-68ff-458c-b30b-00446742dcb2', 'kolay'::difficulty_level, 'Avrupa İnsan Hakları Mahkemesi (AİHM) hangi uluslararası kuruluşa bağlı olarak faaliyet gösterir?', 'AİHM''in bağlı olduğu kuruluşu bilir.', 'AİHM, Avrupa Konseyi''ne bağlı bir yargı organıdır; Avrupa Birliği''nden farklı bir kuruluştur, bu ayrım sıkça karıştırılır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('a8f0613d-dba9-4233-badd-b48be8530583', 'Avrupa Birliği', false, 4);
