insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('e983237c-61da-4bda-9fab-54ebcbe50182', 'ffe5c195-5fea-45a3-9030-58f122e0e1ee', 'zor'::difficulty_level, '''Kitaplık'' sözcüğünün büyük ünlü uyumuna uyup uymadığı ve nedeni aşağıdakilerden hangisinde doğru verilmiştir?', 'Büyük ünlü uyumunu birleşik/ekli sözcüklerde uygular.', '''Kitap'' sözcüğündeki tüm ünlüler (i, a) önce ince-kalın karışık gibi görünse de ''kitaplık'' sözcüğü aslında ''kitap'' (kalın: a) + ''-lık'' (kalın: ı) ekiyle kurulmuştur ve büyük ünlü uyumuna UYAR; çünkü ilk hecedeki ünlü kalın olduğu için sonraki ünlü de kalın gelmiştir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e983237c-61da-4bda-9fab-54ebcbe50182', 'Uymaz, çünkü ''i'' ince bir ünlüdür.', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e983237c-61da-4bda-9fab-54ebcbe50182', 'Uyar, çünkü ilk hece kalın (a) olduğu için sonraki ünlüler de kalın gelmiştir.', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e983237c-61da-4bda-9fab-54ebcbe50182', 'Uymaz, çünkü yabancı kökenli bir sözcüktür.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e983237c-61da-4bda-9fab-54ebcbe50182', 'Uyar, ama yalnızca küçük ünlü uyumu bakımından.', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e983237c-61da-4bda-9fab-54ebcbe50182', 'Bu sözcük ünlü uyumu kurallarının kapsamı dışındadır.', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('4ab1983a-8645-4fb1-9e5e-6a8de59197db', '9683464a-e0ce-493b-ae60-58c924e2ae5c', 'kolay'::difficulty_level, 'Aşağıdaki cümlelerin hangisinde ''de'' bağlacı doğru (ayrı) yazılmıştır?', 'Bağlaç ''de''nin ayrı yazımını uygular.', '''O da bizimle gelecek.'' cümlesinde ''da'' bir bağlaçtır ve cümleden çıkarıldığında (''O bizimle gelecek'') anlam bozulmadığı için doğru biçimde ayrı yazılmıştır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('4ab1983a-8645-4fb1-9e5e-6a8de59197db', 'Sınıfda ders işleniyor.', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('4ab1983a-8645-4fb1-9e5e-6a8de59197db', 'Evde kimse yok.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('4ab1983a-8645-4fb1-9e5e-6a8de59197db', 'O da bizimle gelecek.', true, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('4ab1983a-8645-4fb1-9e5e-6a8de59197db', 'Bahçede oyun oynadılar.', false, 4);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('4ab1983a-8645-4fb1-9e5e-6a8de59197db', 'Kitap masada duruyor.', false, 0);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('f86a05f6-0418-4016-99d4-23769fc0679c', '4d4e66fa-6b06-4194-a222-0ed30c0edd1b', 'orta'::difficulty_level, 'Aşağıdaki cümlelerin hangisinde ünlem işareti (!) doğru ve yerinde kullanılmıştır?', 'Ünlem işaretinin kullanım yerini bilir.', '''Ne kadar da güzel bir manzara!'' cümlesi güçlü bir duygu (hayranlık) bildirdiği için ünlem işaretiyle bitirilmesi doğrudur. Diğer seçenekler soru, düz bilgi veya buyruk niteliğinde olup ünlem gerektirmez ya da yanlış konumda kullanılmıştır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('f86a05f6-0418-4016-99d4-23769fc0679c', 'Bugün hava! çok güzeldi.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('f86a05f6-0418-4016-99d4-23769fc0679c', 'Saat kaçta! geliyorsun?', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('f86a05f6-0418-4016-99d4-23769fc0679c', 'Ne kadar da güzel bir manzara!', true, 4);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('f86a05f6-0418-4016-99d4-23769fc0679c', 'Yarın! okula gideceğim.', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('f86a05f6-0418-4016-99d4-23769fc0679c', 'Kitabı, okudum!, beğendim.', false, 1);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('52347ec1-5711-4b20-befb-3d0b1415af6c', 'd36b15a7-95b8-4c4e-bf33-8e2737e8099e', 'orta'::difficulty_level, '''Bu iş bitene kadar gözünü kırpmadan çalıştı.'' cümlesindeki altı çizili söz grubunun anlamı aşağıdakilerden hangisidir?', 'Deyimlerin anlamını bağlamdan çıkarır.', '''Gözünü kırpmadan'' deyimi burada ''hiç durmadan, yorulmadan, dikkatini hiç dağıtmadan'' anlamında kullanılmıştır; bu, gerçek anlamından tamamen kopmuş mecazi bir deyimdir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('52347ec1-5711-4b20-befb-3d0b1415af6c', 'Uyuyakalarak', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('52347ec1-5711-4b20-befb-3d0b1415af6c', 'Hiç ara vermeden, yorulmadan', true, 4);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('52347ec1-5711-4b20-befb-3d0b1415af6c', 'Gözlerini kapatarak', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('52347ec1-5711-4b20-befb-3d0b1415af6c', 'Yavaş ve dikkatsizce', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('52347ec1-5711-4b20-befb-3d0b1415af6c', 'Çok kısa bir sürede', false, 2);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('5042f057-4f8a-4dcd-a560-e46cacb480a1', 'eb6df17f-05d4-49df-b626-ba5d585672a9', 'zor'::difficulty_level, '''Herkes erken geldiği hâlde toplantı yine de geç başladı.'' cümlesindeki anlam ilişkisi aşağıdakilerden hangisidir?', 'Beklentiye aykırılık (karşıtlık) ilişkisini pekiştirici bir örnekle tanır.', '''-dığı hâlde'' ifadesi, normalde beklenen bir sonucun (herkes erken geldiği için toplantının da erken başlaması) TERSİNİN gerçekleştiğini bildirir; bu beklentiye aykırılık (karşıtlık) ilişkisidir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('5042f057-4f8a-4dcd-a560-e46cacb480a1', 'Neden-sonuç', false, 4);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('5042f057-4f8a-4dcd-a560-e46cacb480a1', 'Amaç-sonuç', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('5042f057-4f8a-4dcd-a560-e46cacb480a1', 'Koşul (şart)', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('5042f057-4f8a-4dcd-a560-e46cacb480a1', 'Beklentiye aykırılık (karşıtlık)', true, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('5042f057-4f8a-4dcd-a560-e46cacb480a1', 'Karşılaştırma', false, 3);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('6bd4d64e-956f-4dbd-bb69-fc0e4027210f', 'f884a167-9e40-4c5c-bc29-810eb13f200e', 'orta'::difficulty_level, 'Bir paragrafın giriş cümlesiyle ilgili aşağıdaki yargılardan hangisi yanlıştır?', 'Paragrafta giriş cümlesinin özelliklerini bilir.', 'Giriş cümlesi konuyu tanıtan, genellikle en genel yargıyı taşıyan cümledir; ancak zamir (bu, şu) veya bağlaçla (ama, çünkü, bu yüzden) BAŞLAMAZ, çünkü bunlar önceki bir cümleye bağlanmayı gerektirir — bir paragrafın en başında böyle bir referans noktası bulunmaz. Bu nedenle ''giriş cümlesi zamirle başlayabilir'' yargısı YANLIŞTIR.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('6bd4d64e-956f-4dbd-bb69-fc0e4027210f', 'Giriş cümlesi konuyu genel hatlarıyla tanıtır.', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('6bd4d64e-956f-4dbd-bb69-fc0e4027210f', 'Giriş cümlesi zamirle (bu, şu, bunlar) başlayabilir.', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('6bd4d64e-956f-4dbd-bb69-fc0e4027210f', 'Giriş cümlesi bağlaçla (ama, çünkü, bu yüzden) başlamaz.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('6bd4d64e-956f-4dbd-bb69-fc0e4027210f', 'Giriş cümlesinden sonra konu ayrıntılandırılır.', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('6bd4d64e-956f-4dbd-bb69-fc0e4027210f', 'Giriş cümlesi paragrafın ilk cümlesidir.', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('1d00eecc-e082-414e-b49f-d9e8bf9478f8', 'cb8b9cfd-ad14-4b82-bfca-b8476e6dfae4', 'zor'::difficulty_level, '''Sınava giren adaylara başarılar dilerim ve umarım kazanırlar.'' cümlesindeki anlatım bozukluğunun nedeni nedir?', 'Farklı çatı/kip kaynaklı anlatım bozukluğunu tespit eder.', 'Cümlede ''dilerim'' (1. tekil şahıs, şimdiki zaman) ile ''kazanırlar'' (3. çoğul şahıs, geniş zaman) arasında ÖZNE VE KİP tutarsızlığı vardır; bu tür cümleler yapıdan kaynaklanan bir anlatım bozukluğu örneğidir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('1d00eecc-e082-414e-b49f-d9e8bf9478f8', 'Gereksiz sözcük kullanımı', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('1d00eecc-e082-414e-b49f-d9e8bf9478f8', 'Anlam belirsizliği', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('1d00eecc-e082-414e-b49f-d9e8bf9478f8', 'Özne ve kip bakımından tutarsızlık', true, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('1d00eecc-e082-414e-b49f-d9e8bf9478f8', 'Çelişen sözlerin bir aradalığı', false, 4);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('1d00eecc-e082-414e-b49f-d9e8bf9478f8', 'Tamlama eksikliği', false, 0);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('a73e5073-8aa5-48d7-b6f1-1314bb7ea52c', '9c8a78d2-c1a7-46f2-9f24-d94b5d9c6d2f', 'orta'::difficulty_level, '12 ve 18 sayılarının EKOK''u (en küçük ortak katı) kaçtır?', 'EKOK hesaplamasını uygular.', '12 = 2²×3 ve 18 = 2×3² biçiminde asal çarpanlarına ayrılır. EKOK, tüm asal çarpanların en büyük kuvvetleri çarpılarak bulunur: 2²×3² = 4×9 = 36.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('a73e5073-8aa5-48d7-b6f1-1314bb7ea52c', '24', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('a73e5073-8aa5-48d7-b6f1-1314bb7ea52c', '30', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('a73e5073-8aa5-48d7-b6f1-1314bb7ea52c', '36', true, 4);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('a73e5073-8aa5-48d7-b6f1-1314bb7ea52c', '48', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('a73e5073-8aa5-48d7-b6f1-1314bb7ea52c', '54', false, 1);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('b13f4b4b-f708-4ebc-9e0b-ec0aa86a7b0c', 'd795c6f3-3a19-4f95-9919-007a184ced02', 'kolay'::difficulty_level, 'Aşağıdaki sayılardan hangisi 9 ile tam bölünür?', '9 ile bölünebilme kuralını uygular.', '9 ile bölünebilme kuralına göre bir sayının rakamları toplamı 9''a bölünmelidir. 351 sayısının rakamları toplamı 3+5+1=9''dur ve 9''a bölünür, bu nedenle 351 de 9 ile tam bölünür.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b13f4b4b-f708-4ebc-9e0b-ec0aa86a7b0c', '341', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b13f4b4b-f708-4ebc-9e0b-ec0aa86a7b0c', '351', true, 4);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b13f4b4b-f708-4ebc-9e0b-ec0aa86a7b0c', '361', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b13f4b4b-f708-4ebc-9e0b-ec0aa86a7b0c', '371', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b13f4b4b-f708-4ebc-9e0b-ec0aa86a7b0c', '381', false, 2);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('a87656ab-1c61-41c2-afa8-a6481143949f', '52e4adee-4581-449e-bf2d-39847a1ff32a', 'orta'::difficulty_level, 'İki basamaklı bir sayının rakamları toplamı 11''dir. Bu sayının onlar basamağı, birler basamağından 3 fazladır. Bu sayı kaçtır?', 'Basamaklar arası ilişkili denklemi çözer.', 'Onlar basamağı x, birler basamağı y olsun: x+y=11 ve x=y+3. İkinci denklemi ilkine yerleştirirsek (y+3)+y=11 → 2y=8 → y=4, dolayısıyla x=7. Sayı 74''tür.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('a87656ab-1c61-41c2-afa8-a6481143949f', '65', false, 4);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('a87656ab-1c61-41c2-afa8-a6481143949f', '74', true, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('a87656ab-1c61-41c2-afa8-a6481143949f', '83', false, 1);
