insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('5e43eef2-c521-42cd-9d23-ed283aa4b80d', '37efade7-3bb5-42a9-9e22-8fcd6c0006b7', 'zor'::difficulty_level, '3/5 ile 5/6 kesirlerinin çarpımının, 1/2''ye bölümü kaçtır?', 'Kesirlerde çarpma ve bölme işlemlerini sırasıyla uygular.', 'Önce çarpma yapılır: (3/5)×(5/6) = 15/30 = 1/2. Ardından bu sonuç 1/2''ye bölünür: (1/2)÷(1/2) = 1.');
