insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('06a8cf26-bc35-4bb8-a97a-773cfa9fe01c', 'f609f88b-2d72-42bc-bdb7-549657da2fd0', 'zor'::difficulty_level, 'Bir havuzu dolduran musluk tek başına 10 saatte, havuzu boşaltan musluk ise tek başına 15 saatte havuzu boşaltabiliyor. Havuz boşken her iki musluk birlikte açılırsa havuz kaç saatte dolar?', 'Doldurma-boşaltma birleşik iş problemini çözer.', 'Dolduran musluğun saatlik iş oranı 1/10, boşaltan musluğun saatlik iş oranı -1/15''tir (havuzu boşalttığı için negatif etki). Birlikte açıldıklarında net oran 1/10 - 1/15 = 3/30 - 2/30 = 1/30 olur; bu da havuzun 30 saatte dolacağı anlamına gelir.');
